'use strict';
let dataCollection='projects',dataPage=0,dataQuery='',aiBusy=false;
const originalRender=render;
const labels={projects:'演出项目',members:'会员档案',tickets:'票务订单',campaigns:'宣传活动',suppliers:'供应商',purchases:'采购订单',employees:'员工档案',ledger:'财务流水',requests:'业务申请',membershipCards:'会员卡',pointsTransactions:'积分流水',refunds:'退票退款',attendance:'员工考勤',payroll:'薪资明细',leaveRequests:'请假申请',recruitment:'招聘岗位'};
async function api(url,body){const response=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await response.json();if(!response.ok)throw Error(data.error||'请求失败');return data;}
function collections(){const d=state.domain||{};return {...d,members:state.members,tickets:state.tickets,ledger:state.ledger,requests:state.requests};}
async function loadDemo(){const d=await api('/api/dataset');if(!d.meta?.synthetic)throw Error('演示数据标记缺失');const merge=(oldRows,newRows)=>{const ids=new Set(oldRows.map(x=>x.id));return [...oldRows,...newRows.filter(x=>!ids.has(x.id))]};state.members=merge(state.members,d.members);state.tickets=merge(state.tickets,d.tickets);state.ledger=merge(state.ledger,d.ledger);state.requests=merge(state.requests,d.requests);state.domain=Object.fromEntries(Object.keys(labels).filter(k=>!['requests','members','tickets','ledger'].includes(k)).map(k=>[k,d[k]||[]]));state.demoVersion=d.meta.dataset;state.seq=Math.max(state.seq,d.seq);persist();render();toast('完整演示数据已载入，保留原有业务记录');}
function tableRows(){return (collections()[dataCollection]||[]).filter(x=>!dataQuery||JSON.stringify(x).toLowerCase().includes(dataQuery.toLowerCase()));}
render=function(){if(['业务数据','真实 AI 接入'].includes(page)){document.getElementById('nav').innerHTML=['总览',...Ops.modules,'审批中心','结果台账','业务数据','真实 AI 接入','操作日志','组件接入'].map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${x}</button>`).join('');app.innerHTML=`<div class="eyebrow">集团管理 AI / ${esc(page)}</div><h1>${esc(page)}</h1><div class="notice">全部业务样本均为虚构。AI 为真实本地模型调用，模型输出供人工复核；业务执行仍使用演示流程。</div><div id="real-content"></div>`;const c=document.getElementById('real-content');
if(page==='真实 AI 接入'){c.innerHTML=`<div class="card"><h2>本地模型连接</h2><p>复用 llama.cpp 推理服务，通过兼容接口接入。无需 API Key，也不发送业务样本到云端。</p><button data-real="status">检查模型连接</button><pre id="model-status">点击检查，读取实际服务状态。</pre><p class="muted">返回任意业务模块，选择草稿或退回事项，点击“真实 AI 分析”。规则模拟建议仍保留用于对照。可通过服务端 .env 切换到兼容 API 或 Dify Chat 应用。</p></div><div class="card"><h2>经营问答</h2><form id="business-query"><label><span>基于演示台账提问</span><input name="question" maxlength="1000" required placeholder="例如：票务净收入是多少？采购有哪些需要关注的问题？"></label><button>查询经营数据并分析</button></form><pre id="business-answer">统计由服务端代码计算，AI 负责解释。这里使用基准台账，不含浏览器新增事项。</pre></div>`;}
else {const sets=collections(),rows=tableRows(),start=dataPage*20;if(start>=rows.length&&dataPage>0)dataPage=0;const shown=rows.slice(dataPage*20,dataPage*20+20),columns=[...new Set(shown.flatMap(x=>Object.keys(x)))].filter(k=>!['advice','result'].includes(k));c.innerHTML=`<div class="stats">${[['项目',sets.projects?.length||0],['会员',state.members.length],['票务订单',state.tickets.length],['财务流水',state.ledger.length]].map(([n,v])=>`<div class="stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><div class="card"><div class="row"><button data-real="load">补充完整演示数据</button><span class="muted">重复补充不会重复导入，不覆盖现有事项。</span></div><p class="muted">${Object.entries(labels).map(([k,v])=>`${v} ${sets[k]?.length||0}`).join(' · ')}</p><form id="data-search" class="row"><select name="collection" style="width:180px">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${dataCollection===k?'selected':''}>${v}</option>`).join('')}</select><input name="query" value="${esc(dataQuery)}" style="width:300px" placeholder="按编号、项目、姓名或状态检索"><button>检索</button></form><p class="muted">匹配 ${rows.length} 条 · 第 ${dataPage+1} / ${Math.max(1,Math.ceil(rows.length/20))} 页 · 支持横向滚动查看全部字段</p><div class="scroll"><table><thead><tr>${columns.map(k=>`<th>${esc(({id:'编号',name:'名称',title:'标题',projectId:'项目编号',memberId:'会员编号',supplierId:'供应商编号',employeeId:'员工编号',ticketId:'票务编号',sourceId:'来源编号',type:'类型',status:'状态',amount:'金额',qty:'数量',date:'日期',department:'部门',role:'岗位',points:'积分',active:'启用',tier:'等级',city:'城市',joinedAt:'加入日期',venue:'场地',budget:'预算',capacity:'容量',owner:'负责人',revenue:'售票收入',refunds:'退款',cost:'项目成本',net:'净额',unitPrice:'单价',channel:'渠道',createdAt:'创建日期',created:'创建时间',project:'演出名称',refundReason:'退款原因',seat:'座位',item:'采购内容',dueDate:'交付日期',rating:'评分',category:'分类',direction:'收支方向',sourceType:'来源类型',spend:'投放支出',impressions:'曝光',clicks:'点击',conversions:'转化',consentMarketing:'营销授权',employmentType:'用工类型',leaveDays:'请假天数',trainingCompleted:'培训完成',expiresAt:'到期日期',issuedAt:'发卡日期',annualFee:'年费',shift:'班次',hours:'工时',month:'月份',gross:'应发',deduction:'扣款',classification:'数据标记',days:'天数',startDate:'开始日期',reason:'原因',headcount:'招聘人数',applications:'应聘数量',ownerId:'负责人编号',module:'业务模块',subject:'业务对象',applicantId:'申请人编号',priority:'优先级'})[k]||k)}</th>`).join('')}</tr></thead><tbody>${shown.map(row=>`<tr>${columns.map(k=>`<td>${esc(typeof row[k]==='object'?JSON.stringify(row[k]):row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="row" style="margin-top:16px"><button data-real="prev-data" ${dataPage===0?'disabled':''}>上一页</button><button data-real="next-data" ${(dataPage+1)*20>=rows.length?'disabled':''}>下一页</button></div><p class="muted">关联方式：票务 memberId 对应会员 id；projectId 对应演出项目；采购 supplierId 对应供应商；财务 sourceId 对应订单或宣传活动。金额为演示人民币。</p></div>`;}}
else {originalRender();const nav=document.getElementById('nav');nav.innerHTML+=`<button data-page="业务数据">业务数据</button><button data-page="真实 AI 接入">真实 AI 接入</button>`;const r=state.requests.find(x=>x.id===selected);if(r&&['草稿','退回'].includes(r.status)){const heading=Array.from(app.querySelectorAll('h2')).find(x=>x.textContent==='事项处理');if(heading){const b=document.createElement('button');b.textContent=aiBusy?'AI 正在分析…':'真实 AI 分析';b.dataset.real='analyze';b.disabled=aiBusy;heading.parentElement.querySelector('.row')?.appendChild(b);}}const requestCard=Array.from(app.querySelectorAll('h2')).find(x=>x.textContent==='业务事项'||x.textContent==='待审批队列');if(requestCard){const rows=state.requests.filter(x=>(page==='审批中心'?x.status==='待审批':Ops.modules.includes(page)?x.module===page:true)&&(!requestQuery||JSON.stringify(x).includes(requestQuery)));const controls=document.createElement('div');controls.innerHTML=`<form id="request-search" class="row"><input name="query" style="width:240px" value="${esc(requestQuery)}" placeholder="检索业务编号、标题、状态"><button>检索</button></form><div class="row" style="margin-top:12px"><button data-real="prev-requests" ${requestPage===0?'disabled':''}>上一页</button><span>第 ${requestPage+1} 页 · ${rows.length} 条</span><button data-real="next-requests" ${(requestPage+1)*20>=rows.length?'disabled':''}>下一页</button></div>`;requestCard.parentElement.appendChild(controls);}if(r?.sourceId&&requestCard){const source=Object.values(collections()).flat().find(x=>x.id===r.sourceId);if(source){const detail=document.createElement('div');detail.className='card';detail.innerHTML=`<h2>关联业务记录 · ${esc(r.sourceId)}</h2><pre>${esc(JSON.stringify(source,null,2))}</pre>`;document.getElementById('content').appendChild(detail);}}}
const notice=app.querySelector('.notice');if(notice&&page!=='业务数据'&&page!=='真实 AI 接入')notice.textContent='面试测试环境：已提供真实本地 AI 分析入口。审批与业务执行为演示；完整样本可在“业务数据”检索。模型服务状态以实际检查结果为准。';};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){requestPage=0;return}if(!b.dataset.real)return;e.stopImmediatePropagation();const a=b.dataset.real;try{if(a==='load')await loadDemo();else if(a==='status'){const r=await api('/api/integrations');document.getElementById('model-status').textContent=JSON.stringify(r,null,2);}else if(a==='analyze'){if(aiBusy)return;const record=state.requests.find(x=>x.id===selected);if(!record||!['草稿','退回'].includes(record.status))throw Error('当前事项不在可分析阶段');const id=record.id;aiBusy=true;render();const r=await api('/api/ai/analyze',{record});const current=state.requests.find(x=>x.id===id);if(!current||!['草稿','退回'].includes(current.status))throw Error('事项状态已改变，分析未写入');current.advice=`真实 AI 分析 · ${r.model} · ${(r.elapsedMs/1000).toFixed(1)} 秒\n\n${r.text}`;state.logs.unshift({at:new Date().toISOString(),id,message:'真实 AI 分析完成，待人工复核'});persist();toast('真实 AI 分析已写入事项');}else if(a==='prev-data')dataPage=Math.max(0,dataPage-1);else if(a==='next-data')dataPage++;else if(a==='prev-requests')requestPage=Math.max(0,requestPage-1);else if(a==='next-requests')requestPage++;}catch(err){toast(err.message)}finally{aiBusy=false;if(a!=='status')render();}},true);
document.addEventListener('submit',e=>{if(e.target.id==='business-query'){e.preventDefault();e.stopImmediatePropagation();const question=new FormData(e.target).get('question');const output=document.getElementById('business-answer');output.textContent='正在计算并调用本地模型…';api('/api/ai/business-query',{question}).then(r=>{output.textContent=r.text+'\n\n确定性统计（以此为准）：\n'+JSON.stringify(r.facts,null,2)}).catch(err=>output.textContent=err.message);return;}if(!['data-search','request-search'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const form=new FormData(e.target);if(e.target.id==='data-search'){dataCollection=form.get('collection');dataQuery=form.get('query').trim();dataPage=0;}else{requestQuery=form.get('query').trim();requestPage=0;}render();},true);
render();if(state.demoVersion!=='culture-ops-sqlite-v4')loadDemo().catch(e=>toast('完整样本未载入：'+e.message));
